
/* Gate 5: drag, scroll or press arrow keys to walk the path; each lantern lights; the end cuts to Contact */
(function(){
var reduce=matchMedia('(prefers-reduced-motion: reduce)').matches,body=document.body,gate=document.getElementById('jgate'),knob=document.getElementById('jknob'),msg=document.getElementById('jmsg');
var lis=[].slice.call(document.querySelectorAll('#tl li')),n=lis.length,val=0,base=0,sx=0,drag=false,done=false,RANGE=220,lit=0;
var LAN='<img class="lan" alt="" aria-hidden="true" src="data:image/png;base64,">';
function say(){msg.textContent=lit<n?'Walk the path — lantern '+(lit+1)+' of '+n:'The gate is near — keep walking'}
function set(v){val=Math.max(0,Math.min(1,v));window.__expVal=val;gate.style.setProperty('--p',val);
 while(lit<n&&val>=(lit+1)/(n+1)){lis[lit].classList.add('lit');if(navigator.vibrate)navigator.vibrate(20);lit++;say()}
 if(val>=1&&!done)finish()}
function finish(){done=true;drag=false;if(navigator.vibrate)navigator.vibrate([20,30,50]);
 Slash(function(){location.hash='contact';body.classList.add('jdone')})}
window.__expSet=set;window.__expVal=0;
if(reduce||!n){body.classList.add('jdone')}else{
 lis.forEach(function(li){li.insertAdjacentHTML('afterbegin',LAN)});say();
 gate.addEventListener('pointerdown',function(e){if(done||e.button>0)return;drag=true;sx=e.clientX;base=val;try{gate.setPointerCapture(e.pointerId)}catch(x){}});
 gate.addEventListener('pointermove',function(e){if(drag)set(base+(e.clientX-sx)/RANGE)});
 ['pointerup','pointercancel'].forEach(function(ev){gate.addEventListener(ev,function(){drag=false})});
 knob.addEventListener('keydown',function(e){if(done)return;if(e.key==='ArrowRight'||e.key===' '||e.key==='Enter'){e.preventDefault();set(val+.2)}else if(e.key==='ArrowLeft'){e.preventDefault();set(val-.2)}});
 document.getElementById('experience').addEventListener('wheel',function(e){if(done||!body.classList.contains('jv'))return;set(val+e.deltaY/900)},{passive:true});
}
document.addEventListener('portfolio:view',function(e){body.classList.toggle('jv',e.detail.id==='experience')});
if(location.hash==='#experience')body.classList.add('jv');
})();
